use runtime_bridge::service::{Service,approved_pop,stop_worker};
use std::{collections::VecDeque,future::Future,task::{Context,Poll,Waker},sync::{Arc,atomic::{AtomicBool,Ordering}},time::Duration};
use tokio::sync::{Mutex,oneshot};
#[tokio::test] async fn later_snapshot_and_contention(){let s=Service::default();let(a,b)=tokio::time::timeout(Duration::from_secs(1),async{tokio::join!(s.increment_and_snapshot(),s.increment_and_snapshot())}).await.unwrap();assert!(a>=1&&b>=1);assert_eq!(s.snapshot().await,2);}
#[tokio::test] async fn closed_approval_and_waiting_lock_preserve_queue(){let q=Mutex::new(VecDeque::from([7]));let(tx,rx)=oneshot::channel();drop(tx);assert_eq!(approved_pop(&q,rx).await,None);let guard=q.lock().await;let(tx,rx)=oneshot::channel();tx.send(()).unwrap();let mut f=Box::pin(approved_pop(&q,rx));assert!(matches!(f.as_mut().poll(&mut Context::from_waker(Waker::noop())),Poll::Pending));drop(f);drop(guard);assert_eq!(q.lock().await.pop_front(),Some(7));}
struct Dropped(Arc<AtomicBool>);impl Drop for Dropped {fn drop(&mut self){self.0.store(true,Ordering::SeqCst);}}
#[tokio::test] async fn stop_waits_for_destructor(){let flag=Arc::new(AtomicBool::new(false));let copy=flag.clone();let(tx,rx)=oneshot::channel();let worker=tokio::spawn(async move{let _drop=Dropped(copy);tx.send(()).unwrap();std::future::pending::<()>().await;});rx.await.unwrap();tokio::time::timeout(Duration::from_secs(1),stop_worker(worker)).await.unwrap();assert!(flag.load(Ordering::SeqCst));}
#[tokio::test] async fn blocking_worker_is_joined(){let(start_tx,start_rx)=oneshot::channel();let(release_tx,release_rx)=std::sync::mpsc::channel();let done=Arc::new(AtomicBool::new(false));let d=done.clone();let worker=tokio::task::spawn_blocking(move||{start_tx.send(()).unwrap();release_rx.recv_timeout(Duration::from_secs(2)).unwrap();d.store(true,Ordering::SeqCst);});start_rx.await.unwrap();let mut stop=Box::pin(stop_worker(worker));assert!(matches!(stop.as_mut().poll(&mut Context::from_waker(Waker::noop())),Poll::Pending));release_tx.send(()).unwrap();tokio::time::timeout(Duration::from_secs(2),stop).await.unwrap();assert!(done.load(Ordering::SeqCst));}
